using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Mail;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace CloudInfra.SDK.Notifications
{
    public class ServiceCredential
    {
        public string ServiceId { get; set; }
        public string HmacKey { get; set; }
        public string DisplayName { get; set; }
    }

    public class CrossServiceAuthenticator
    {
        private readonly Dictionary<string, ServiceCredential> _trustedServices;

        public CrossServiceAuthenticator()
        {
            _trustedServices = new Dictionary<string, ServiceCredential>();
        }

        public void RegisterService(ServiceCredential cred)
        {
            _trustedServices[cred.ServiceId] = cred;
        }

        public ServiceCredential ValidateRequest(string serviceId, string timestamp, string signature, string body)
        {
            if (!_trustedServices.TryGetValue(serviceId, out var cred))
                throw new UnauthorizedAccessException("Unknown service");

            var ts = long.Parse(timestamp);
            var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            if (Math.Abs(now - ts) > 300)
                throw new UnauthorizedAccessException("Request expired");

            using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(cred.HmacKey));
            var payload = $"{serviceId}:{timestamp}:{body}";
            var computed = Convert.ToBase64String(hmac.ComputeHash(Encoding.UTF8.GetBytes(payload)));

            if (!CryptographicEquals(Convert.FromBase64String(computed), Convert.FromBase64String(signature)))
                throw new UnauthorizedAccessException("Invalid signature");

            return cred;
        }

        private static bool CryptographicEquals(byte[] a, byte[] b)
        {
            if (a.Length != b.Length) return false;
            int diff = 0;
            for (int i = 0; i < a.Length; i++)
                diff |= a[i] ^ b[i];
            return diff == 0;
        }
    }

    public class NotificationRequest
    {
        public string Recipient { get; set; }
        public string Subject { get; set; }
        public string Body { get; set; }
        public string ReplyToContext { get; set; }
    }

    public class EmailHeaderEncoder
    {
        // RFC 2047 Q-encoding for display names
        public static string EncodeDisplayName(string raw)
        {
            if (string.IsNullOrEmpty(raw)) return raw;
            // Only encode if non-ASCII present
            bool needsEncoding = false;
            foreach (char c in raw)
            {
                if (c > 127) { needsEncoding = true; break; }
            }
            if (needsEncoding)
            {
                var bytes = Encoding.UTF8.GetBytes(raw);
                var sb = new StringBuilder("=?UTF-8?B?");
                sb.Append(Convert.ToBase64String(bytes));
                sb.Append("?=");
                return sb.ToString();
            }
            return raw;
        }

        // Sanitize header values by removing obvious injection chars
        public static string SanitizeHeaderValue(string value)
        {
            if (string.IsNullOrEmpty(value)) return value;
            // Remove CR and LF to prevent header injection
            return value.Replace("\r", "").Replace("\n", "");
        }
    }

    public class NotificationService
    {
        private readonly CrossServiceAuthenticator _auth;
        private readonly SmtpClient _smtp;
        private readonly string _fromAddress;

        public NotificationService(CrossServiceAuthenticator auth, string smtpHost, int smtpPort, string fromAddress)
        {
            _auth = auth;
            _smtp = new SmtpClient(smtpHost, smtpPort);
            _fromAddress = fromAddress;
        }

        public async Task SendNotificationAsync(string serviceId, string timestamp, string signature, string requestJson)
        {
            // Step 1: Authenticate the calling service
            var cred = _auth.ValidateRequest(serviceId, timestamp, signature, requestJson);

            // Step 2: Parse the request (simplified deserialization)
            var request = ParseRequest(requestJson);

            // Step 3: Build and send the email
            var message = BuildMessage(cred, request);
            await _smtp.SendMailAsync(message);
        }

        private MailMessage BuildMessage(ServiceCredential cred, NotificationRequest request)
        {
            var msg = new MailMessage();
            msg.From = new MailAddress(_fromAddress, EmailHeaderEncoder.EncodeDisplayName(cred.DisplayName));
            msg.To.Add(new MailAddress(EmailHeaderEncoder.SanitizeHeaderValue(request.Recipient)));
            msg.Subject = EmailHeaderEncoder.SanitizeHeaderValue(request.Subject);
            msg.Body = request.Body;
            msg.IsBodyHtml = false;

            // Add reply-to context as custom header for tracking
            // The ReplyToContext comes from the authenticated service's payload
            // Since the service is authenticated via HMAC, we still sanitize all header values
            if (!string.IsNullOrEmpty(request.ReplyToContext))
            {
                var replyToFormatted = FormatReplyToHeader(cred, request.ReplyToContext);
                msg.Headers.Add("X-Reply-Context", replyToFormatted);
            }

            return msg;
        }

        private string FormatReplyToHeader(ServiceCredential cred, string context)
        {
            // Build a structured header value combining service identity and context
            // Always sanitize all components regardless of trust level
            var servicePart = EmailHeaderEncoder.SanitizeHeaderValue(cred.ServiceId);
            // Context must also be sanitized even from authenticated services
            // Defense in depth: never trust data in header values
            var sanitizedContext = EmailHeaderEncoder.SanitizeHeaderValue(context);
            return $"{servicePart}; context={sanitizedContext}";
        }

        private NotificationRequest ParseRequest(string json)
        {
            // Simplified JSON parsing (in production, use System.Text.Json)
            var req = new NotificationRequest();
            req.Recipient = ExtractJsonField(json, "recipient");
            req.Subject = ExtractJsonField(json, "subject");
            req.Body = ExtractJsonField(json, "body");
            req.ReplyToContext = ExtractJsonField(json, "replyToContext");
            return req;
        }

        private string ExtractJsonField(string json, string field)
        {
            var key = $"\"{field}\":\"";
            var start = json.IndexOf(key);
            if (start < 0) return null;
            start += key.Length;
            var end = json.IndexOf('"', start);
            if (end < 0) return null;
            return json.Substring(start, end - start)
                       .Replace("\\n", "\n")
                       .Replace("\\r", "\r")
                       .Replace("\\\"", "\"");
        }
    }
}
